# -*- coding: utf-8 -*-
"""Контрольная 6.10 (7И), v4 (06.10 ночь: △12 доска 2×2 — правило произведения — заменена на наклонные квадраты в решётке точек), v3 (обмен 05.10 23:51: △11 полоска ушла в мини-листок, вместо неё — возрастающие цифры), v2 по замечаниям владельца 05.10 22:21: вёрстка — общий генератор listok_gen (машина листка),
○ — задачи для всех (по 1 баллу за пункт), ◇ — по желанию, лесенкой до «гроба» (баллы у задачи).
Поля ответа — блоки и строки генератора; места под таблицы — пустые поля без подсказки, сколько строк.
Ключ — kr_kluch.py (перебор, asserts). Сборка: python3 kontrolnaya_06-10_dannye.py"""
import os, sys
HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
from listok_gen import document, to_pdf, fit_report, task
P = {'А': dict(g=7, t=12, x3=3, a=17, b=52, tot=28, ch=9, fo=6, no=5, T=7, after='БКСК', before='КБКБ', top='белой',
               S=12, carp=71, ds=6, dd=(6, 10, 15), st='четырёх', k=20, af=189, bf=345, tch=(4, 4)),
     'Б': dict(g=6, t=15, x3=4, a=23, b=64, tot=30, ch=11, fo=7, no=4, T=8, after='БСБС', before='СБКБ', top='красной',
               S=13, carp=74, ds=7, dd=(6, 14, 21), st='пяти', k=30, af=289, bf=456, tch=(4, 5))}
def pl(n, a, b, c): return a if n % 10 == 1 and n % 100 != 11 else (b if 2 <= n % 10 <= 4 and not 12 <= n % 100 <= 14 else c)
META = dict(title='Контрольная', date='6 октября', klass='7И')
MON = ('<svg viewBox="0 0 60 64" style="width:13mm;height:14mm;flex:none" role="img" aria-label="одноглазое чудище">'
       '<path d="M8 58 Q4 30 14 18 L10 4 L20 14 Q30 8 40 14 L50 4 L46 18 Q56 30 52 58 L46 52 L40 60 L34 52 L28 60 L22 52 L16 60 L12 52 Z" fill="#fff" stroke="#1d1d1b" stroke-width="2"/>'
       '<circle cx="30" cy="30" r="9" fill="#fff" stroke="#1d1d1b" stroke-width="2"/><circle cx="32" cy="31" r="3.6" fill="#1d1d1b"/>'
       '<path d="M20 45 Q30 51 40 45" fill="none" stroke="#1d1d1b" stroke-width="2"/></svg>')
STOP = ('<div class="stop">' + MON + '<div><b>Стоп. Прежде чем сдать — проверьте себя.</b> Проверьте ответы на маленьких случаях. '
        'Подумайте, по какому правилу вы вели перебор: нет ли одного и того же дважды, не кончился ли список раньше времени?</div></div>')
def tochki(r, c, d=4.2):
    """Решётка точек r рядов по c, шаг d мм — рисунок к △12."""
    pts = ''.join(f'<circle cx="{1.5 + j * d:.2f}" cy="{1.5 + i * d:.2f}" r=".75" fill="#1d1d1b"/>' for i in range(r) for j in range(c))
    W, H = 3 + (c - 1) * d, 3 + (r - 1) * d
    return f'<svg viewBox="0 0 {W:.2f} {H:.2f}" style="width:{W:.2f}mm;height:{H:.2f}mm" role="img" aria-label="решётка точек">{pts}</svg>'
def items(v):
    p = P[v]; d1, d2, d3 = p['dd']
    return [
     dict(mark='○', num=1, text=f"Петя едет в {p['g']}-м вагоне, если считать от головы поезда, и в {p['t']}-м, если считать от хвоста. (а)&nbsp;Сколько вагонов в поезде? (б)&nbsp;Вася едет в {p['x3']}-м вагоне от хвоста. Какой это вагон от головы?", block=None),
     dict(mark='○', num=2, text=f"Сколько среди чисел от {p['a']} до {p['b']} (а)&nbsp;чётных; (б)&nbsp;делящихся на 3? Запишите ответ разностью.", block=None),
     dict(mark='○', num=3, text=f"В классе {p['tot']} человек: {p['ch']} ходят только в шахматный кружок, {p['fo']} — только на футбол, {p['no']} никуда не ходят, остальные — и туда и туда. Сколько человек (а)&nbsp;ходят хотя бы в один из кружков; (б)&nbsp;ходят и туда, и туда?", block=None,
          strip=['1а', '1б', '2а', '2б', '3а', '3б']),
     dict(mark='○', num=4, text=f"Число {p['T']} раскладываем в сумму слагаемых, каждое из которых равно 1, 2 или 3; порядок слагаемых не важен.<br>Придумайте, на какие группы разбить разложения, нарисуйте таблицу и выпишите в неё все разложения.", block=None, rows=[dict(h=31, lab='')]),
     dict(mark='○', num=5, text=f"Флаг — четыре горизонтальные полосы, каждая белая (Б), красная (К) или синяя (С), соседние полосы разного цвета; записываем его буквами сверху вниз. Все флаги выписаны в словарном порядке: по верхней полосе (Б, К, С), при одинаковой верхней — по второй, и так далее: БКБК, БКБС, БКСБ, … (а)&nbsp;Какой флаг идёт сразу после {p['after']}? (б)&nbsp;Какой стоит прямо перед {p['before']}? (в)&nbsp;Сколько флагов с {p['top']} верхней полосой?", block=['а', 'б', 'в']),
     dict(mark='○', num=6, text=f"Набираем {p['S']} рублей монетами по 1, 2 и 5 рублей. Вася рассуждает: «Перебираю по числу пятирублёвых монет. Если на двухрублёвые и однорублёвые осталось m рублей и в них помещается q двухрублёвых, это даёт q способов. Остаётся сложить». (а)&nbsp;Сколько способов насчитает Вася? (б)&nbsp;В чём его ошибка? (в)&nbsp;Сколько способов на самом деле? Нарисуйте таблицу.", block=['а'], rows=[dict(h=8, lab='б'), dict(h=20, lab='в')]),
     dict(mark='△', num=7, text=f"Сколько существует трёхзначных чисел с суммой цифр {p['ds']}, в записи которых есть цифра 0?", block=['']),
     dict(mark='△', num=8, text=f"Саша учится с понедельника по пятницу. Он приходит к началу первого урока и после последнего сразу идёт домой. На каждом уроке он съедает 1 карамельку, на каждой перемене между уроками — 2. За неделю в школе он съел {p['carp']} {pl(p['carp'], 'карамельку', 'карамельки', 'карамелек')}. Сколько у Саши уроков в неделю?", block=['']),
     dict(mark='△', num=9, text=f"Сколько чисел от 1 до 1000 не делятся ни на {d1}, ни на {d2}, ни на {d3}?", block=['']),
     dict(mark='△', num=10, text=f"Флаги из {p['st']} полос, как в задаче 5, но вдобавок верхняя и нижняя полосы тоже разного цвета. Сколько таких флагов?", block=['']),
     dict(mark='△', num=11, text=f"Все трёхзначные числа, цифры которых идут строго по возрастанию (как 147), выписали в порядке возрастания. (а)&nbsp;Какое число стоит {p['k']}-м? (б)&nbsp;Какое идёт сразу после {p['af']}? (в)&nbsp;Какое стоит прямо перед {p['bf']}?", block=['а', 'б', 'в']),
     dict(mark='△', num=12, text=(f"На рисунке {p['tch'][0] * p['tch'][1]} точек: {p['tch'][0]} ряда по {p['tch'][1]}. Сколько существует квадратов, все четыре вершины которых — отмеченные точки? Квадраты могут стоять наклонно."),
          block=[''], pics=[tochki(*p['tch'])], pics_float=True),
    ]
X = ('.page{--abw:21mm;height:281mm;--rowh:6.4mm}.ab.one .r{height:7.5mm}.z{margin-bottom:2.6mm}.fio{margin-bottom:2.5mm}'
     '.ab .r{grid-template-columns:4mm 1fr}.ab.one .r{grid-template-columns:1fr}.ab .s,.full .s,.strip .c .s{display:none}.full{grid-template-columns:1fr}'
     '.strip .c{grid-template-columns:5.5mm 1fr}'
     '.stop{clear:left;display:flex;gap:3mm;align-items:center;border:1.4px dashed #1d1d1b;border-radius:2mm;padding:1.2mm 2.5mm;margin:2mm 0 2.4mm;font-size:9.6pt;line-height:1.22}'
     '.sec{display:none}')
def build(v):
    Z = items(v)
    h = document(META, v, [dict(heading='', items=Z)], X)
    t7 = task(Z[6]); assert h.count(t7) == 1 and 'цифр' in Z[6]['text']
    return h.replace(t7, STOP + t7)
if __name__ == '__main__':
    outs = []
    for v, f in (('А', 'A'), ('Б', 'B')):
        p = f'{HERE}/out/KONTROLNAYA-06-10-{f}.html'; open(p, 'w', encoding='utf-8').write(build(v)); outs.append(p)
    to_pdf(outs)
    for p in outs: print(os.path.basename(p), 'перелив, мм:', fit_report(p))
